import{_ as o,a0 as n,w as l,s as p,I as s,x as e,a1 as t,A as a,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"如何在 Linux 系统中使用 dd 命令而不会损毁你的磁盘 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 系统中使用 dd 命令而不会损毁你的磁盘 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 系统中使用 dd 命令而不会损毁你的磁盘 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 系统中使用 dd 命令而不会损毁你的磁盘 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180705 How to use dd in Linux without destroying your disk","title":"如何在 Linux 系统中使用 dd 命令而不会损毁你的磁盘","tag":"201807","desc":""},"relativePath":"201807/20180705 How to use dd in Linux without destroying your disk.md","filePath":"[post].md"}'),u={name:"201807/20180705 How to use dd in Linux without destroying your disk.md"};function h(g,d,c,k,b,f){const i=n("Link");return l(),p("div",null,[d[18]||(d[18]=s("h1",{id:"如何在-linux-系统中使用-dd-命令而不会损毁你的磁盘",tabindex:"-1"},[e("如何在 Linux 系统中使用 dd 命令而不会损毁你的磁盘 "),s("a",{class:"header-anchor",href:"#如何在-linux-系统中使用-dd-命令而不会损毁你的磁盘","aria-label":"Permalink to “如何在 Linux 系统中使用 dd 命令而不会损毁你的磁盘”"},"​")],-1)),d[19]||(d[19]=s("blockquote",null,[s("p",null,"使用 Linux 中的 dd 工具安全、可靠地制作一个驱动器、分区和文件系统的完整镜像。")],-1)),d[20]||(d[20]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/computer_happy_sad_developer_programming.png?itok=72nkfSQ_",alt:""})],-1)),s("p",null,[s("em",null,[d[1]||(d[1]=e("这篇文章节选自 Manning 出版社出版的图书 ",-1)),t(i,{href:"https://www.manning.com/books/linux-in-action?a_aid=bootstrap-it&a_bid=4ca15fc9&chan=opensource"},{default:a(()=>[...d[0]||(d[0]=[e("Linux in Action",-1)])]),_:1}),d[2]||(d[2]=e("的第 4 章。",-1))])]),d[21]||(d[21]=r(`<p>你是否正在从一个即将损坏的存储驱动器挽救数据，或者要把本地归档进行远程备份，或者要把一个别处的活动分区做个完整的副本，那么你需要懂得如何安全而可靠的复制驱动器和文件系统。幸运的是，<code>dd</code> 是一个可以使用的简单而又功能强大的镜像复制命令，从现在到未来很长的时间内，也许直到永远都不会出现比 <code>dd</code> 更好的工具了。</p><h3 id="对驱动器和分区做个完整的副本" tabindex="-1">对驱动器和分区做个完整的副本 <a class="header-anchor" href="#对驱动器和分区做个完整的副本" aria-label="Permalink to “对驱动器和分区做个完整的副本”">​</a></h3><p>仔细研究后，你会发现你可以使用 <code>dd</code> 做各种任务，但是它最重要的功能是处理磁盘分区。当然，你可以使用 <code>tar</code> 命令或者 <code>scp</code> 命令从一台计算机复制整个文件系统的文件，然后把这些文件原样粘贴在另一台刚刚安装好 Linux 操作系统的计算机中。但是，因为那些文件系统归档不是完整的映像文件，所以在复制文件的过程中需要计算机操作系统的运行作为基础。</p><p>另一方面，使用 <code>dd</code> 可以对任何数字信息完美的进行逐个字节的镜像。但是不论何时何地，当你要对分区进行操作时，我要告诉你早期的 Unix 管理员曾开过这样的玩笑：“ dd 的意思是<ruby>磁盘毁灭者<rt>disk destroyer</rt></ruby>”（LCTT 译注：<code>dd</code> 原意是<ruby>磁盘复制<rt>disk dump</rt></ruby>）。 在使用 <code>dd</code> 命令的时候，如果你输入了哪怕是一个字母，也可能立即永久性的擦除掉整个磁盘驱动器里的所有重要的数据。因此，一定要注意命令的拼写格式规范。</p><p><strong>记住：</strong> 在按下回车键执行 <code>dd</code> 命令之前，暂时停下来仔细的认真思考一下。</p><h3 id="dd-命令的基本操作" tabindex="-1">dd 命令的基本操作 <a class="header-anchor" href="#dd-命令的基本操作" aria-label="Permalink to “dd 命令的基本操作”">​</a></h3><p>现在你已经得到了适当的提醒，我们将从简单的事情开始。假设你要对代号为 <code>/dev/sda</code> 的整个磁盘数据创建精确的映像，你已经插入了一块空的磁盘驱动器 （理想情况下具有与代号为 <code>/dev/sda</code> 的磁盘驱动器相同的容量）。语法很简单： <code>if=</code> 定义源驱动器，<code>of=</code> 定义你要将数据保存到的文件或位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dd if=/dev/sda of=/dev/sdb</span></span></code></pre></div><p>接下来的例子将要对 <code>/dev/sda</code> 驱动器创建一个 .img 的映像文件，然后把该文件保存的你的用户帐号家目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dd if=/dev/sda of=/home/username/sdadisk.img</span></span></code></pre></div><p>上面的命令针对整个驱动器创建映像文件，你也可以针对驱动器上的单个分区进行操作。下面的例子针对驱动器的单个分区进行操作，同时使用了一个 <code>bs</code> 参数用于设置单次拷贝的字节数量 （此例中是 4096）。设定 <code>bs</code> 参数值可能会影响 <code>dd</code> 命令的整体操作速度，该参数的理想设置取决于你的硬件配置和其它考虑。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dd if=/dev/sda2 of=/home/username/partition2.img bs=4096</span></span></code></pre></div><p>数据的恢复非常简单：通过颠倒 <code>if</code> 和 <code>of</code> 参数可以有效的完成任务。在此例中，<code>if=</code> 使用你要恢复的映像，<code>of=</code> 使用你想要写入映像的目标驱动器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dd if=sdadisk.img of=/dev/sdb</span></span></code></pre></div><p>你也可以在一条命令中同时完成创建和拷贝任务。下面的例子中将使用 SSH 从远程驱动器创建一个压缩的映像文件，并把该文件保存到你的本地计算机中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ssh username@54.98.132.10 &quot;dd if=/dev/sda | gzip -1 -&quot; | dd of=backup.gz</span></span></code></pre></div><p>你应该经常测试你的归档，确保它们可正常使用。如果它是你创建的启动驱动器，将它粘贴到计算机中，看看它是否能够按预期启动。如果它是普通分区的数据，挂载该分区，确保文件都存在而且可以正常的访问。</p><h3 id="使用-dd-擦除磁盘数据" tabindex="-1">使用 dd 擦除磁盘数据 <a class="header-anchor" href="#使用-dd-擦除磁盘数据" aria-label="Permalink to “使用 dd 擦除磁盘数据”">​</a></h3><p>多年以前，我的一个负责政府海外大使馆安全的朋友曾经告诉我，在他当时在任的时候， 政府会给每一个大使馆提供一个官方版的锤子。为什么呢？ 一旦大使馆设施可能被不友善的人员侵占，就会使用这个锤子毁坏所有的硬盘.</p><p>为什么要那样做？为什么不是删除数据就好了？你在开玩笑，对吧？所有人都知道从存储设备中删除包含敏感信息的文件实际上并没有真正移除这些数据。除非使用锤子彻底的毁坏这些存储介质，否则，只要有足够的时间和动机, 几乎所有的内容都可以从几乎任何数字存储介质重新获取。</p><p>但是，你可以使用 <code>dd</code> 命令让坏人非常难以获得你的旧数据。这个命令需要花费一些时间在 <code>/dev/sda1</code> 分区的每个扇区写入数百万个 <code>0</code>（LCTT 译注：是指 0x0 字节，意即 NUL ，而不是数字 0 ）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dd if=/dev/zero of=/dev/sda1</span></span></code></pre></div><p>还有更好的方法。通过使用 <code>/dev/urandom</code> 作为源文件，你可以在磁盘上写入随机字符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dd if=/dev/urandom of=/dev/sda1</span></span></code></pre></div><h3 id="监控-dd-的操作" tabindex="-1">监控 dd 的操作 <a class="header-anchor" href="#监控-dd-的操作" aria-label="Permalink to “监控 dd 的操作”">​</a></h3><p>由于磁盘或磁盘分区的归档可能需要很长的时间，因此你可能需要在命令中添加进度查看器。安装管道查看器（在 Ubuntu 系统上安装命令为 <code>sudo apt install pv</code>），然后把 <code>pv</code> 命令和 <code>dd</code> 命令结合在一起。使用 <code>pv</code>，最终的命令是这样的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dd if=/dev/urandom | pv | dd of=/dev/sda1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4,14MB 0:00:05 [ 98kB/s] [      &lt;=&gt;                  ]</span></span></code></pre></div><p>想要推迟备份和磁盘管理工作？有了 <code>dd</code> 工具，你不会有太多的借口。它真的非常简单，但是要小心。祝你好运！</p><hr>`,29)),s("p",null,[d[4]||(d[4]=e("via：",-1)),t(i,{href:"https://opensource.com/article/18/7/how-use-dd-linux"},{default:a(()=>[...d[3]||(d[3]=[e("https://opensource.com/article/18/7/how-use-dd-linux",-1)])]),_:1})]),s("p",null,[d[9]||(d[9]=e("作者：",-1)),t(i,{href:"https://opensource.com/users/remyd"},{default:a(()=>[...d[5]||(d[5]=[e("David Clinton",-1)])]),_:1}),d[10]||(d[10]=e(" 选题：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:a(()=>[...d[6]||(d[6]=[e("lujun9972",-1)])]),_:1}),d[11]||(d[11]=e(" 译者：",-1)),t(i,{href:"https://github.com/SunWave"},{default:a(()=>[...d[7]||(d[7]=[e("SunWave",-1)])]),_:1}),d[12]||(d[12]=e(" 校对：",-1)),t(i,{href:"https://github.com/wxy"},{default:a(()=>[...d[8]||(d[8]=[e("wxy",-1)])]),_:1})]),s("p",null,[d[15]||(d[15]=e("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...d[13]||(d[13]=[e("LCTT",-1)])]),_:1}),d[16]||(d[16]=e(" 原创编译，",-1)),t(i,{href:"https://linux.cn/"},{default:a(()=>[...d[14]||(d[14]=[e("Linux中国",-1)])]),_:1}),d[17]||(d[17]=e(" 荣誉推出",-1))])])}const y=o(u,[["render",h]]);export{v as __pageData,y as default};
